insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m046', 'k-geometry', 2, 'في نشاط فني أراد طالب تزيين أطراف لوحة مربعة باستخدام شريط لاصق، فقصّ منه مقدارًا يغطي جميع جوانب اللوحة بالكامل. إذا كان طول ضلع اللوحة 5 سم، فكم سنتيمترًا من الشريط استخدم؟', '["10","15","20","25"]'::jsonb, 2, 'تزيين الأطراف يعني المحيط لا المساحة: محيط المربع = 4 × الضلع = 4 × 5 = 20 سم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m047', 'k-geometry', 3, 'يمشي ناصر حول حديقة مربعة الشكل، طول المسافة حولها 1.4 كيلومتر. إذا مشى ناصر مسافة 4.9 كيلومترات، فكم مرة تقريبًا دار حول الحديقة؟', '["مرتان ونصف","ثلاث مرات","ثلاث مرات ونصف","أربع مرات"]'::jsonb, 2, 'عدد الدورات = المسافة الكلية ÷ المحيط = 4.9 ÷ 1.4 = 3.5 أي ثلاث مرات ونصف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m048', 'k-geometry', 2, 'في ملعب المدرسة حُددت منطقة مستطيلة الشكل مخصّصة للعبة القفز، بحيث يكون طولها 20 مترًا وعرضها 12 مترًا. ما مقدار الأرض التي ستُستخدم لتنفيذ اللعبة داخل هذه المنطقة؟', '["32 مترًا مربعًا","64 مترًا مربعًا","240 مترًا مربعًا","400 مترًا مربعًا"]'::jsonb, 2, 'مقدار الأرض المستخدمة = المساحة = الطول × العرض = 20 × 12 = 240 م². (لو طُلب السياج حولها لكان المحيط 64 مترًا).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m049', 'k-geometry', 2, 'يمشي فهد حول حديقة مستطيلة الشكل يوميًا، طولها 18 مترًا وعرضها 7 أمتار. فكم مترًا يمشي في يومين؟', '["25","50","100","126"]'::jsonb, 2, 'المشي حولها يعني المحيط = 2 × (18 + 7) = 50 مترًا يوميًا، وفي يومين = 100 متر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m050', 'k-geometry', 2, 'قصّت المعلمة قطعة ورقية على شكل مثلث قاعدته 6 سم وارتفاعه العمودي عليها 4 سم، ثم ألصقتها داخل كراسة أحد الطلاب. ما عدد السنتيمترات المربعة التي غطّتها القطعة؟', '["10","12","20","24"]'::jsonb, 1, 'مساحة المثلث = (القاعدة × الارتفاع) ÷ 2 = (6 × 4) ÷ 2 = 12 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m051', 'k-geometry', 3, 'مثلث مساحته 25 سم²، وارتفاعه العمودي على القاعدة يساوي 5 سم. ما طول قاعدته؟', '["5","10","15","20"]'::jsonb, 1, 'من قانون المساحة: القاعدة = (المساحة × 2) ÷ الارتفاع = (25 × 2) ÷ 5 = 10 سم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m052', 'k-geometry', 2, 'صمّم الطالب مهند علَمًا على شكل معين، وكان طول قطره الأكبر 10 سم وقطره الأصغر 6 سم. ما مساحة هذا العلم؟', '["30 سم²","32 سم²","36 سم²","40 سم²"]'::jsonb, 0, 'مساحة المعين = (حاصل ضرب القطرين) ÷ 2 = (10 × 6) ÷ 2 = 30 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m053', 'k-geometry', 2, 'رسمت الطالبة هدى دائرة نصف قطرها 1 سم. ما أقرب مساحة يمكن اعتمادها لهذه الدائرة؟', '["2 سم²","3 سم²","4 سم²","5 سم²"]'::jsonb, 1, 'مساحة الدائرة = π × نق² = 3.14 × 1 = 3.14، وأقرب قيمة هي 3 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m054', 'k-geometry', 2, 'رسمت الطالبة سارة دائرة نصف قطرها 3 سم. ما مساحة هذه الدائرة تقريبًا؟', '["22 سم²","24 سم²","26 سم²","28 سم²"]'::jsonb, 3, 'مساحة الدائرة = π × نق² = 3.14 × 9 = 28.26 ≈ 28 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m055', 'k-geometry', 2, 'أراد مروان عمل سور حول مزرعته دائرية الشكل التي يبلغ طول قطرها 4 كيلومترات. ما طول السور الذي يحتاجه تقريبًا بالكيلومتر؟', '["9 كم","11 كم","12 كم","13 كم"]'::jsonb, 3, 'السور يمثل المحيط = π × القطر = 3.14 × 4 = 12.56 ≈ 13 كم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m056', 'k-geometry', 3, 'أحاط حمد مزرعته الدائرية بسياج طوله 66 مترًا. ما طول قطر المزرعة تقريبًا؟', '["16 مترًا","21 مترًا","26 مترًا","31 مترًا"]'::jsonb, 1, 'من قانون المحيط: القطر = المحيط ÷ π = 66 ÷ (22/7) = 66 × 7 ÷ 22 = 21 مترًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m057', 'k-geometry', 2, 'صنعت ريم صندوقًا صغيرًا على شكل مكعب وغطّته من الخارج بورق لاصق من جميع الجوانب. إذا كان طول ضلع المكعب 2 سم، فكم سنتيمترًا مربعًا من الورق استخدمت لتغطيته كاملًا؟', '["8 سم²","12 سم²","18 سم²","24 سم²"]'::jsonb, 3, 'مساحة سطح المكعب = 6 × (الضلع × نفسه) = 6 × 4 = 24 سم². والقيمة 8 هي الحجم لا المساحة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m058', 'k-geometry', 1, 'صنعت نورة مجسمًا على شكل مكعب من الخشب، وكان طول ضلعه 2 سم. ما حجم هذا المجسم؟', '["4 سم³","6 سم³","8 سم³","12 سم³"]'::jsonb, 2, 'حجم المكعب = الضلع × الضلع × الضلع = 2 × 2 × 2 = 8 سم³.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m059', 'k-geometry', 3, 'غرفة على شكل مكعب حجمها 216 م³. فكم يكون طول ضلع الغرفة بالمتر؟', '["1","3","6","10"]'::jsonb, 2, 'الضلع = الجذر التكعيبي للحجم؛ ولأن 6 × 6 × 6 = 216 فطول الضلع 6 أمتار.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m060', 'k-geometry', 3, 'صمّم يوسف مجسمًا على شكل هرم، قاعدته مربعة طول ضلعها 3 سم وارتفاعه العمودي 4 سم. ما حجم هذا الهرم؟', '["12 سم³","18 سم³","24 سم³","36 سم³"]'::jsonb, 0, 'حجم الهرم = ⅓ × مساحة القاعدة × الارتفاع = ⅓ × (3 × 3) × 4 = ⅓ × 36 = 12 سم³.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m061', 'k-units', 2, 'صفّ عمّال البناء 60 بلاطة طول كل واحدة منها 20 سم، بحيث وُضعت جميعها بجانب بعضها على خط مستقيم. ما طول هذا الصف بالمتر؟', '["10","12","14","16"]'::jsonb, 1, 'الطول الكلي = 60 × 20 = 1200 سم، وبالتحويل إلى المتر نقسم على 100: 1200 ÷ 100 = 12 مترًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m062', 'k-units', 2, 'قادت ليلى سيارتها داخل المدينة لقطع مشوار بلغ طوله 9000 متر، وكانت سيارتها تستهلك 3 لترات من الوقود لكل كيلومتر تقطعه. كم لترًا من الوقود استهلكت خلال هذا المشوار؟', '["18","21","24","27"]'::jsonb, 3, 'نحوّل أولًا: 9000 متر = 9 كيلومترات، ثم الاستهلاك = 9 × 3 = 27 لترًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m063', 'k-units', 2, 'قام الطالب يزيد بلصق ثماني قطع خشبية صغيرة بجانب بعضها، وكان طول كل قطعة منها 25 مليمترًا. كم يبلغ الطول الكلي للقطع الثماني بالسنتيمتر؟', '["2","10","14","20"]'::jsonb, 3, 'الطول الكلي = 8 × 25 = 200 مليمتر، وبالقسمة على 10 نحصل على 20 سنتيمترًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m064', 'k-units', 2, 'يقوم عامل بطلاء أنبوب طوله 2400 متر مقابل 50 ريالًا عن كل كيلومتر ينجزه. فكم يحصل العامل مقابل طلاء هذا الأنبوب كاملًا؟', '["100","110","120","130"]'::jsonb, 2, '2400 متر = 2.4 كيلومتر، والأجرة = 2.4 × 50 = 120 ريالًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m065', 'k-units', 1, 'تتناول فاطمة يوميًا 1500 جرام من الأرز. فكم يكون مجموع ما تتناوله خلال أربعة أيام بالكيلوجرام؟', '["4","5","6","7"]'::jsonb, 2, 'المجموع = 1500 × 4 = 6000 جرام، وبالقسمة على 1000 يكون 6 كيلوجرامات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m066', 'k-units', 1, 'اشترى راشد كيسين من الطحين يزن كل كيس 3 كيلوجرامات. ما الوزن الكلي للطحين الذي اشتراه بالجرام؟', '["300","600","3000","6000"]'::jsonb, 3, 'الوزن = 2 × 3 = 6 كيلوجرامات، وبالضرب في 1000 يكون 6000 جرام.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m067', 'k-units', 2, 'اشترى ناصر 200 جرام من القهوة بمبلغ 50 ريالًا. فكم يكون سعر الكيلوجرام الواحد من هذا النوع؟', '["150","200","225","250"]'::jsonb, 3, 'الكيلوجرام = 1000 جرام = 5 أضعاف الـ200 جرام، فالسعر = 50 × 5 = 250 ريالًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m068', 'k-units', 2, 'أثناء تحضير وجبة جماعية استخدمت منال المكونات الآتية: 500 جرام من الطحين، و750 جرامًا من السكر، و0.5 كيلوجرام من الزبدة، و250 جرامًا من المكسرات. ما الكتلة الكلية للمكونات بالكيلوجرام؟', '["1.5","2","2.5","3"]'::jsonb, 1, 'نوحّد الوحدات أولًا: 0.5 كجم = 500 جرام، فيكون المجموع = 500 + 750 + 500 + 250 = 2000 جرام = 2 كيلوجرام.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m069', 'k-units', 1, 'ملأت سارة ثلاث زجاجات عصير سعة كل واحدة منها نصف لتر. ما كمية العصير التي ملأتها بالمليلتر؟', '["1000","1200","1500","1800"]'::jsonb, 2, 'الكمية = 3 × 0.5 = 1.5 لتر، وبالضرب في 1000 تكون 1500 مليلتر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m070', 'k-units', 1, 'يشرب خالد كل يوم 800 مليلتر من الماء. فكم يشرب خلال خمسة أيام باللتر؟', '["3","4","5","6"]'::jsonb, 1, 'المجموع = 800 × 5 = 4000 مليلتر، وبالقسمة على 1000 يكون 4 لترات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m071', 'k-units', 3, 'ركّب عامل سياجًا حول حديقة مربعة طول ضلعها 10 ياردات. كم يكون الطول الكلي للسياج بوحدة القدم؟', '["30","60","90","120"]'::jsonb, 3, 'المحيط = 4 × 10 = 40 ياردة، والياردة = 3 أقدام، فالطول = 40 × 3 = 120 قدمًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m072', 'k-units', 3, 'تنقل شاحنة صغيرة مواد بناء يوميًا بوزن 600 رطل. فكم يبلغ الوزن الكلي الذي تنقله خلال 5 أيام بوحدة الطن؟', '["1.5","2","2.5","3"]'::jsonb, 0, 'الوزن الكلي = 600 × 5 = 3000 رطل، والطن = 2000 رطل، فالنتيجة = 3000 ÷ 2000 = 1.5 طن.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m073', 'k-units', 3, 'يخزّن فهد في مستودعه سائل تنظيف في براميل كبيرة، كل برميل يسع 3 جالونات من السائل. إذا أراد فهد تعبئة هذا السائل في عبوات صغيرة تسع كل منها كوارتًا واحدًا، فكم عبوة يمكنه تعبئتها من كل برميل؟', '["8","10","12","16"]'::jsonb, 2, 'الجالون = 4 كوارتات، فيكون البرميل = 3 × 4 = 12 كوارتًا، أي 12 عبوة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m074', 'k-stats', 1, 'يُعد عدد أفراد الأسرة متغيرًا:', '["وصفيًا","نوعيًا","كميًا منفصلًا","كميًا متصلًا"]'::jsonb, 2, 'عدد الأفراد يُقاس بالأرقام فهو كمي، وقيمه أعداد صحيحة لا تقبل الكسور (لا يوجد نصف فرد) فهو منفصل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m075', 'k-stats', 1, 'طلبت المعلمة من طلابها أن يحددوا فصول السنة التي يفضلونها: الربيع، الصيف، الخريف، الشتاء. ما نوع مقياس القياس المستخدم في هذا السؤال؟', '["اسمي","رتبي","فئوي","نسبي"]'::jsonb, 0, 'فصول السنة تصنيف وصفي بلا ترتيب أو أفضلية بينها، فالمقياس اسمي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m076', 'k-stats', 2, 'في استبانة طُلب من الطالبات تحديد نوع النشاط المدرسي الذي شاركن فيه (علمي، ثقافي، رياضي)، ثم اختيار التقدير الذي حصلن عليه في نهاية السنة (ممتاز، جيد جدًا، جيد). ما نوع مقياسي القياس المستخدمين على التوالي؟', '["اسمي، رتبي","رتبي، اسمي","اسمي، فئوي","رتبي، نسبي"]'::jsonb, 0, 'نوع النشاط تصنيف بلا ترتيب (اسمي)، أما التقديرات فمرتبة تصاعديًا في الجودة (رتبي).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m077', 'k-stats', 3, 'يُعد المقياس النسبي أعلى مستويات القياس لأنه يجمع خصائص المقاييس الأخرى: ترتيب القيم وتساوي الفواصل ووجود صفر حقيقي. كل ما يلي يُعد مثالًا لبيانات تُقاس بالمقياس النسبي، ما عدا:', '["وزن الطالب","عمر المعلم","عدد الحصص","درجة ذكاء الطالب"]'::jsonb, 3, 'درجة الذكاء ليس لها صفر حقيقي (لا يوجد ذكاء يساوي صفرًا مطلقًا)، فهي تُقاس بالمقياس الفئوي لا النسبي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m078', 'k-stats', 2, 'يضم أحد الفصول الدراسية 60 طالبًا، ويرغب المعلم في تمثيلهم حسب نوع النشاط المدرسي المفضل لديهم (رياضي، ثقافي، علمي، فني). ما التمثيل البياني الأنسب من بين الآتي؟', '["المدرج التكراري","المنحنى البياني","المضلع التكراري","القطاعات الدائرية"]'::jsonb, 3, 'البيانات نوعية اسمية ويُراد بيان نصيب كل نوع من المجموع، والقطاعات الدائرية أفضل ما يمثل الجزء بالنسبة إلى الكل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m079', 'k-stats', 2, 'قدّم المعلم لطلابه جدولًا يبيّن توزيع مصادر دخل الأسرة (مثل: راتب، استثمار، دعم حكومي)، وطلب منهم مقارنة نسبة كل مصدر إلى إجمالي الدخل. ما التمثيل البياني الأنسب لهذه البيانات؟', '["التمثيل بالأعمدة","التمثيل بالخطوط","التمثيل بالقطاعات الدائرية","التمثيل بالنقاط"]'::jsonb, 2, 'عبارة «نسبة كل مصدر إلى الإجمالي» تدل على مقارنة الجزء بالكل، وهذا مجال القطاعات الدائرية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m080', 'k-stats', 2, 'أجرت المعلمة نشاطًا قارنت فيه عدد الكتب التي قرأها طلاب مجموعة من الصفوف المختلفة خلال الشهر، وأرادت تمثيل هذه البيانات بطريقة تُبرز الفروق بين الصفوف. ما التمثيل البياني الأنسب لذلك؟', '["القطاعات الدائرية","الأعمدة البيانية","المضلع التكراري","الخطوط البيانية"]'::jsonb, 1, 'المطلوب مقارنة أعداد بين فئات منفصلة (صفوف)، والأعمدة أوضح ما يُبرز الفروق بينها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m081', 'k-stats', 2, 'أراد المعلّم تمثيل تغير درجات الحرارة اليومية خلال أسبوع باستخدام تمثيل يُظهر التغير المستمر في القيم على مدى زمني منتظم. ما التمثيل البياني الأنسب لهذا الغرض؟', '["التمثيل بالأعمدة","التمثيل بالقطاعات الدائرية","التمثيل بالنقاط","التمثيل بالخط البياني"]'::jsonb, 3, 'الخط البياني هو الأنسب لإظهار التغير عبر الزمن، ويُستخدم كذلك في التنبؤ بالاتجاه المستقبلي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m082', 'k-stats', 2, 'أجرى المعلم اختبارًا لمادة الرياضيات على طلاب الصف الثالث، ثم صنّف درجاتهم إلى فئات متساوية (من 0 – 10، 11 – 20، 21 – 30 ...) وسجّل عدد الطلاب في كل فئة. ما الشكل البياني الأنسب لعرض هذه البيانات؟', '["القطاعات الدائرية","المدرجات التكرارية","الأعمدة المنفصلة","أشكال فن"]'::jsonb, 1, 'البيانات كمية مبوّبة في فئات متصلة، والمدرج التكراري (أعمدة متلاصقة) هو الشكل المخصص لعرض هذا التوزيع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m083', 'k-stats', 2, 'يستخدم شكل المدرج التكراري عندما تكون البيانات:', '["نوعية ترتيبية","نوعية اسمية","كمية منفصلة","كمية متصلة"]'::jsonb, 3, 'المدرج التكراري يُبنى على فئات متصلة، فأعمدته متلاصقة دلالةً على اتصال البيانات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m084', 'k-stats', 3, 'وزّعت المعلمة درجات اختبار العلوم على فئات (من 10 إلى أقل من 20، ومن 20 إلى أقل من 30 ...)، ثم أرادت تحديد عدد الطالبات اللاتي حصلن على أقل من 50 درجة من بين جميع الطالبات بناءً على الفئات المتدرجة. ما الشكل البياني الأنسب لهذا النوع من التحليل؟', '["الأعمدة البيانية المنفصلة","المدرج التكراري للفئات","القطاعات الدائرية","المنحنى التكراري التراكمي"]'::jsonb, 3, 'عبارة «عدد من حصلن على أقل من حد معين» تدل على التكرار المتجمع، والمنحنى التكراري التراكمي (المتجمع الصاعد) هو المخصص لذلك.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m085', 'k-central', 1, 'الدرجات التالية تمثل نتائج عدد من الطلاب: 6، 9، 7، 6، 10، 8، 6، 7، 9. ما المنوال لهذه الدرجات؟', '["6","7","9","10"]'::jsonb, 0, 'المنوال هو القيمة الأكثر تكرارًا، والعدد 6 تكرر ثلاث مرات وهو أعلى تكرار في المجموعة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m086', 'k-central', 1, 'خلال هذا الفصل الدراسي خضعت الطالبة منى لخمسة اختبارات قصيرة في مادة العلوم، وكانت درجاتها فيها على التوالي: 7، 8، 9، 6، 10. ما المتوسط الحسابي لدرجات منى في هذه الاختبارات؟', '["7","8","9","10"]'::jsonb, 1, 'المتوسط الحسابي = مجموع القيم ÷ عددها = (7+8+9+6+10) ÷ 5 = 40 ÷ 5 = 8.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m087', 'k-central', 3, 'كان المتوسط الحسابي للطالب فيصل في أربع مواد 9 درجات، وأضاف معلم إحدى هذه المواد 4 درجات لكل طالب. فكم يصبح المتوسط الحسابي الجديد؟', '["7","8","10","11"]'::jsonb, 2, 'المجموع القديم = 9 × 4 = 36، وبإضافة 4 درجات يصبح 40، فالمتوسط الجديد = 40 ÷ 4 = 10. أي أن الزيادة توزعت على عدد المواد.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m088', 'k-central', 3, 'إذا كان المتوسط الحسابي للقيم (6، 3، 5، س) هو 6، فما قيمة س؟', '["7","8","10","11"]'::jsonb, 2, 'المجموع المطلوب = المتوسط × العدد = 6 × 4 = 24، ومجموع القيم المعلومة = 14، فتكون س = 24 − 14 = 10.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m089', 'k-central', 3, 'شعبة (أ) عدد طلابها 6 ومتوسط درجاتهم 10، وشعبة (ب) عدد طلابها 4 ومتوسط درجاتهم 15. فما المتوسط الحسابي لدرجات طلاب الشعبتين معًا؟', '["9","10","12","25"]'::jsonb, 2, 'لا يصح جمع المتوسطين وقسمتهما لاختلاف العددين؛ بل نستخدم المتوسط الموزون: (6×10 + 4×15) ÷ (6+4) = (60+60) ÷ 10 = 12.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m090', 'k-central', 3, 'في أحد الفصول الدراسية حصل طالب على الدرجات التالية في ثلاث مواد جامعية: الرياضيات 3 درجات (وعدد ساعاتها 3)، والعلوم 5 درجات (وعدد ساعاتها 2)، والحاسب 11 درجة (وعدد ساعاتها 1). ما الوسط الحسابي الموزون لدرجات الطالب؟', '["6","5","4","7"]'::jsonb, 1, 'الوسط الموزون = مجموع (الدرجة × ساعاتها) ÷ مجموع الساعات = (3×3 + 5×2 + 11×1) ÷ 6 = (9+10+11) ÷ 6 = 30 ÷ 6 = 5.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
